-- risk: additive
-- 0066: the stage start date of the FAO-56 Kc curve (spec
-- docs/superpowers/specs/2026-09-27-daily-agronomy-parity-design.md, B2).
-- irrigation_zones.stage_started_on is the day the current growth stage began
-- (YYYY-MM-DD, NULL = not set); the daily agronomy row freezes the value with
-- its Kc, together with FAO's day in the stage and whether it passed the stage
-- length. sync-init-fn recreates trg_sync_zones_outbox_au at every boot from
-- scripts/sync-trigger-source.json; the CREATE below is byte-identical to that
-- entry, so a date change alone emits ZONE_CONFIG_UPSERTED and every zone
-- payload carries 'stage_started_on' (null when unset). 0065's rule for
-- 'weather_source' (present only when not 'auto' or changed in this update) is
-- unchanged: the new pair sits in both branches of its CASE.
ALTER TABLE irrigation_zones ADD COLUMN stage_started_on TEXT;
ALTER TABLE zone_daily_agronomy ADD COLUMN stage_started_on TEXT;
ALTER TABLE zone_daily_agronomy ADD COLUMN kc_stage_day INTEGER;
ALTER TABLE zone_daily_agronomy ADD COLUMN stage_overrun INTEGER;
DROP TRIGGER IF EXISTS trg_sync_zones_outbox_au;
CREATE TRIGGER trg_sync_zones_outbox_au AFTER UPDATE ON irrigation_zones FOR EACH ROW WHEN EXISTS (SELECT 1 FROM sync_link_state WHERE peer_node='cloud' AND linked=1) AND (COALESCE(NEW.name,'') <> COALESCE(OLD.name,'') OR COALESCE(NEW.zone_uuid,'') <> COALESCE(OLD.zone_uuid,'') OR COALESCE(NEW.gateway_device_eui,'') <> COALESCE(OLD.gateway_device_eui,'') OR COALESCE(NEW.timezone,'') <> COALESCE(OLD.timezone,'') OR COALESCE(NEW.latitude,'') <> COALESCE(OLD.latitude,'') OR COALESCE(NEW.longitude,'') <> COALESCE(OLD.longitude,'') OR COALESCE(NEW.phenological_stage,'') <> COALESCE(OLD.phenological_stage,'') OR COALESCE(NEW.stage_started_on,'') <> COALESCE(OLD.stage_started_on,'') OR COALESCE(NEW.calibration_key,'') <> COALESCE(OLD.calibration_key,'') OR COALESCE(NEW.crop_type,'') <> COALESCE(OLD.crop_type,'') OR COALESCE(NEW.variety,'') <> COALESCE(OLD.variety,'') OR COALESCE(NEW.soil_type,'') <> COALESCE(OLD.soil_type,'') OR COALESCE(NEW.irrigation_method,'') <> COALESCE(OLD.irrigation_method,'') OR COALESCE(NEW.area_m2,'') <> COALESCE(OLD.area_m2,'') OR COALESCE(NEW.irrigation_efficiency_pct,'') <> COALESCE(OLD.irrigation_efficiency_pct,'') OR COALESCE(NEW.scheduling_mode,'local') <> COALESCE(OLD.scheduling_mode,'local') OR COALESCE(NEW.prediction_card_enabled,0) <> COALESCE(OLD.prediction_card_enabled,0) OR COALESCE(NEW.notes,'') <> COALESCE(OLD.notes,'') OR COALESCE(NEW.weather_source,'auto') <> COALESCE(OLD.weather_source,'auto') OR COALESCE(NEW.deleted_at,'') <> COALESCE(OLD.deleted_at,'') OR COALESCE(NEW.sync_version,0) <> COALESCE(OLD.sync_version,0)) BEGIN INSERT INTO sync_outbox(event_uuid, aggregate_type, aggregate_key, op, payload_json, sync_version, occurred_at, gateway_device_eui) VALUES (lower(hex(randomblob(16))), 'ZONE', COALESCE(NEW.zone_uuid, lower(hex(randomblob(16)))), CASE WHEN NEW.deleted_at IS NOT NULL THEN 'ZONE_DELETED' WHEN COALESCE(NEW.latitude,'') <> COALESCE(OLD.latitude,'') OR COALESCE(NEW.longitude,'') <> COALESCE(OLD.longitude,'') THEN 'ZONE_LOCATION_UPSERTED' WHEN COALESCE(NEW.phenological_stage,'') <> COALESCE(OLD.phenological_stage,'') OR COALESCE(NEW.stage_started_on,'') <> COALESCE(OLD.stage_started_on,'') OR COALESCE(NEW.calibration_key,'') <> COALESCE(OLD.calibration_key,'') OR COALESCE(NEW.crop_type,'') <> COALESCE(OLD.crop_type,'') OR COALESCE(NEW.variety,'') <> COALESCE(OLD.variety,'') OR COALESCE(NEW.soil_type,'') <> COALESCE(OLD.soil_type,'') OR COALESCE(NEW.irrigation_method,'') <> COALESCE(OLD.irrigation_method,'') OR COALESCE(NEW.area_m2,'') <> COALESCE(OLD.area_m2,'') OR COALESCE(NEW.irrigation_efficiency_pct,'') <> COALESCE(OLD.irrigation_efficiency_pct,'') OR COALESCE(NEW.scheduling_mode,'local') <> COALESCE(OLD.scheduling_mode,'local') OR COALESCE(NEW.prediction_card_enabled,0) <> COALESCE(OLD.prediction_card_enabled,0) OR COALESCE(NEW.notes,'') <> COALESCE(OLD.notes,'') OR COALESCE(NEW.weather_source,'auto') <> COALESCE(OLD.weather_source,'auto') THEN 'ZONE_CONFIG_UPSERTED' ELSE 'ZONE_UPSERTED' END, CASE WHEN COALESCE(NEW.weather_source,'auto') <> 'auto' OR OLD.weather_source IS NOT NEW.weather_source THEN json_patch(json_object('contract_version', 1, 'zone_uuid', NEW.zone_uuid, 'name', NEW.name, 'gateway_device_eui', COALESCE(NEW.gateway_device_eui, NULLIF(trim((SELECT gateway_device_eui FROM sync_link_state WHERE peer_node='cloud')),'')), 'timezone', NEW.timezone, 'latitude', NEW.latitude, 'longitude', NEW.longitude, 'phenological_stage', NEW.phenological_stage, 'stage_started_on', NEW.stage_started_on, 'calibration_key', NEW.calibration_key, 'crop_type', NEW.crop_type, 'variety', NEW.variety, 'soil_type', NEW.soil_type, 'irrigation_method', NEW.irrigation_method, 'area_m2', NEW.area_m2, 'irrigation_efficiency_pct', NEW.irrigation_efficiency_pct, 'scheduling_mode', COALESCE(NEW.scheduling_mode, 'local'), 'prediction_card_enabled', COALESCE(NEW.prediction_card_enabled, 0), 'notes', NEW.notes, 'sync_version', NEW.sync_version, 'deleted_at', NEW.deleted_at, 'user', json_object('user_uuid', (SELECT user_uuid FROM users WHERE id = NEW.user_id), 'username', (SELECT username FROM users WHERE id = NEW.user_id), 'cloudUserId', (SELECT cloud_user_id FROM users WHERE id = NEW.user_id))), json_object('weather_source', COALESCE(NEW.weather_source,'auto'))) ELSE json_object('contract_version', 1, 'zone_uuid', NEW.zone_uuid, 'name', NEW.name, 'gateway_device_eui', COALESCE(NEW.gateway_device_eui, NULLIF(trim((SELECT gateway_device_eui FROM sync_link_state WHERE peer_node='cloud')),'')), 'timezone', NEW.timezone, 'latitude', NEW.latitude, 'longitude', NEW.longitude, 'phenological_stage', NEW.phenological_stage, 'stage_started_on', NEW.stage_started_on, 'calibration_key', NEW.calibration_key, 'crop_type', NEW.crop_type, 'variety', NEW.variety, 'soil_type', NEW.soil_type, 'irrigation_method', NEW.irrigation_method, 'area_m2', NEW.area_m2, 'irrigation_efficiency_pct', NEW.irrigation_efficiency_pct, 'scheduling_mode', COALESCE(NEW.scheduling_mode, 'local'), 'prediction_card_enabled', COALESCE(NEW.prediction_card_enabled, 0), 'notes', NEW.notes, 'sync_version', NEW.sync_version, 'deleted_at', NEW.deleted_at, 'user', json_object('user_uuid', (SELECT user_uuid FROM users WHERE id = NEW.user_id), 'username', (SELECT username FROM users WHERE id = NEW.user_id), 'cloudUserId', (SELECT cloud_user_id FROM users WHERE id = NEW.user_id))) END, NEW.sync_version, strftime('%Y-%m-%dT%H:%M:%fZ','now'), COALESCE(NEW.gateway_device_eui, NULLIF(trim((SELECT gateway_device_eui FROM sync_link_state WHERE peer_node='cloud')),''))); END;
